class Solution {
    public int stoneGameVIII(int[] stones){
        int[] prefix=new int[stones.length];
        prefix[0]=stones[0];
        for(int i=1;i<stones.length;i++)prefix[i]=prefix[i-1]+stones[i];
        int best=prefix[stones.length-1];
        for(int i=stones.length-2;i>=1;i--)best=Math.max(best,prefix[i]-best);
        return best;
    }
}

code.kotlin:
class Solution {
    fun stoneGameVIII(stones:IntArray):Int{
        val prefix=IntArray(stones.size);
        prefix[0]=stones[0];
        for(i in 1 until stones.size)prefix[i]=prefix[i-1]+stones[i];
        var best=prefix.last();
        for(i in stones.size-2 downTo 1)best=maxOf(best,prefix[i]-best);
        return best
    }
}

